// =============================================================================
// Assets — runtime loader for the game PNG assets
//
// assets/faces: one cartoon face per named roster piece (all 31 BB2025
// races, 127 unique pieces, incl. linemen), generated by the one-off
// tool /tmp/draw_faces.cpp and committed here. assets/faces.txt maps the
// exact roster position name -> file slug ("Zombie Lineman" -> zombie_lineman).
// assets/skills + assets/cards are drawn by tools/gen_assets.cpp.
//
// The loader locates the assets (compile-time FUMBBL_ASSETS_DIR >
// <exe>/../assets > CWD/assets), caches pixmaps, and falls back to a
// generic face / generic icon when something is missing.
//
// Team colors (home/away) are NOT baked into the faces: the UI draws the
// team-colored circle behind the face at runtime.
// =============================================================================
#pragma once

#include <QPixmap>
#include <QString>

namespace assets {

// Resolved assets directory (empty string when not found).
QString assetsDir();

// --- name -> slug maps (loaded from *_names.txt / faces.txt) ----------------
// Slug for a skill/card name (case-insensitive; "generic" when unknown).
QString skillIconSlug(const QString &skillName);
QString cardIconSlug(const QString &cardName);

// Slug for a roster POSITION NAME ("Ogre", "Zombie Lineman", "Troll Slayer"
// ...). Case-insensitive exact match against faces.txt first, then a direct
// slugification of the name, then the generic fallback.
QString faceSlug(const QString &positionName);

// --- cached pixmaps ----------------------------------------------------------
// Face for a roster position name. Unknown names (e.g. custom-named star
// pieces like "Count Luthor von Drakenborg") fall back to the RACE's
// representative face (raceHint), then to the generic human face.
// Returns a null pixmap only when the whole asset set is missing.
QPixmap playerFace(const QString &positionName, const QString &raceHint = QString());
QPixmap skillPixmap(const QString &skillName);
QPixmap cardPixmap(const QString &cardName);

// True when the face set is available.
bool isAvailable();

} // namespace assets
